class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def min_flips(L: int) -> int:
            if L == 1:
                # Final string must be alternating; try both patterns.
                # Pattern starting with '0': position i should be '0' if i even else '1'.
                mismatches0 = 0
                for i, ch in enumerate(s):
                    expected = '0' if i % 2 == 0 else '1'
                    if ch != expected:
                        mismatches0 += 1
                # The other pattern needs exactly n - mismatches0 flips.
                return min(mismatches0, n - mismatches0)
            # L >= 2: each maximal run of length `run` needs run // (L + 1) flips.
            flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run = j - i
                flips += run // (L + 1)
                i = j
            return flips

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if min_flips(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Values > threshold can never have an edge:
        # lcm(a, b) >= max(a, b) > threshold for any partner b.
        index_of = {}
        big = 0
        for i, v in enumerate(nums):
            if v > threshold:
                big += 1
            else:
                index_of[v] = i

        n = len(nums)
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # For each possible gcd g, gather present values that are multiples of g.
        # For a = g*x, b = g*y (both multiples of g): gcd(a, b) >= g, so
        # lcm(a, b) = a*b / gcd(a,b) <= a*b / g.
        # Hence a*b <= g*threshold  ==>  lcm(a,b) <= threshold  (no gcd needed).
        # Conversely, any edge (a,b) with lcm <= threshold is discovered when
        # g = gcd(a,b), since then lcm = a*b/g <= threshold  ==>  a*b <= g*threshold.
        for g in range(1, threshold + 1):
            limit = g * threshold
            group = []
            m = g
            while m <= threshold:
                if m in index_of:
                    group.append(m)
                m += g
            k = len(group)
            if k < 2:
                continue
            # group is sorted ascending (m iterated upward).
            # For each i, union with all j > i while group[i]*group[j] <= limit.
            for i in range(k - 1):
                ai = group[i]
                idx_ai = index_of[ai]
                for j in range(i + 1, k):
                    aj = group[j]
                    if ai * aj > limit:
                        break
                    union(idx_ai, index_of[aj])

        roots = set()
        for i in index_of.values():
            roots.add(find(i))
        return len(roots) + big
